<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Accessor\RoleRelyingPartyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the RoleRelyingPartyAccessor trait.
 *
 * Covers null default, string/VO assignment via withRelyingParty,
 * getRelyingParty/relyingParty accessors, and isRelyingPartyChanged with/without original.
 */
class RoleRelyingPartyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRelyingParty creates a new instance with the RelyingParty set
     * from a string value, and getRelyingParty returns the primitive string.
     */
    public function testWithRelyingPartyFromString(): void
    {
        // Arrange
        $holder = new ImplWithRoleRelyingPartyAccessorUnitTest();

        // Act
        $result = $holder->withRelyingParty(new RelyingPartyRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new RelyingPartyRef('one'), $result->getRelyingParty());
    }
    /**
     * Asserts that withrelyingParty has access to the value object
     * from a string value, and getRelyingParty returns the primitive string.
     */
    public function testWithRelyingPartyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithRoleRelyingPartyAccessorUnitTest();

        // Act
        $result = $holder->withRelyingParty(new RelyingPartyRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new RelyingPartyRef('one'), $result->relyingParty()->value());
    }
    public function testChangedRelyingParty(): void
    {
        // Arrange
        $holder = new ImplWithRoleRelyingPartyAccessorUnitTest();
        $original = $holder->withRelyingParty(new RelyingPartyRef('one'));
        $same = $holder->withRelyingParty(new RelyingPartyRef('one'));
        $modified = $holder->withRelyingParty(new RelyingPartyRef('other'));

        // Act
        $unchanged = $holder->isRelyingPartyChanged();
        $withSame = $original->isRelyingPartyChanged($same);
        $withDiferent = $original->isRelyingPartyChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithRoleRelyingPartyAccessorUnitTest
{
    use RoleRelyingPartyAccessor;
}
